head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > P > maxlength]<br/>컴포넌트에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "한 문자의 길이를 1 로 계산(다국어 포함)하여 입력 가능한 최대 길이를 숫자로 설정합니다.",
        "값을 설정하지 않으면 '-1' 로 적용되어 입력을 제한하지 않습니다.",
        "datatype=float 일때 '.' 문자를 기준으로 정수부와 소수부의 최대 길이를 각각 설정할 수 있습니다. (ex-'.2')",
        "datatype=float 일때 '.' 문자를 기준으로 정수부에 '*' 를 설정하거나 생략 시 정수부 입력 제한이 없습니다. (ex-'*.2', '.2')",
        "datatype=float 일때 '.' 문자를 기준으로 소수부에 '*' 또는 '-1' 설정 시 소수부 입력 제한이 없습니다. (ex-'5.*', '5.-1')",
        "datatype=float 일때 '.' 문자 없이 숫자만 설정 시 정수부 최대 길이로 적용되고, 소수부는 입력할 수 없습니다.",
        "datatype=float 일때 '*' 또는 '*.' 설정 시 정수부만 제한 없이 입력할 수 있습니다.",
        "datatype=float 일때 '.' 문자만 설정 시 전체 입력이 제한됩니다.",     
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text = function(target) {    
    let rtn = '';
    let tagName = target.render.tagName

    if (tagName !== "INPUT") {
        rtn = target.render.textContent
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);    
    }
    else {
        rtn = target.render.value
        wf_body_bottom.getObj("scwin").setReturnValue("text : " + rtn);   
    }    
}



// target1
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라마바사");
    target1.focus();
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text(target1);
}

